const D = { energy: .65, scale: 1, hue: 45, speed: 1, density: .5, segs: 9, gust: .7, face: 1, x: .5, y: .96, style: 'carlot', seed: 0, act: 'flail' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const u = Math.min(width, height);
const bx = P.x * width, by = P.y * height;
const N = Math.max(4, Math.min(16, Math.round(P.segs)));
const bodyH = u * 0.52 * P.scale;
const segLen = bodyH / N;
const maxW = u * 0.075 * P.scale;
const style = P.style;
const wire = style === 'blueprint';
const neon = style === 'neon';
const chrome = style === 'chrome';
const riso = style === 'riso';

// smoothed audio
S.bass = (S.bass || 0) * .8 + (A.bass || 0) * .2;
S.tre = (S.tre || 0) * .8 + (A.treble || 0) * .2;

// ---- init physics ----
if (!S.seg || S.n !== N) {
  S.n = N; S.seg = []; for (let i = 0; i < N; i++) S.seg.push({ ang: 0, vel: 0 });
  S.armL = [{ ang: 0, vel: 0 }, { ang: 0, vel: 0 }, { ang: 0, vel: 0 }];
  S.armR = [{ ang: 0, vel: 0 }, { ang: 0, vel: 0 }, { ang: 0, vel: 0 }];
  S.amp = .6;
}

// ---- dramaturgy: per-section inflation program ----
const ACT = {
  flail:    [.7,.9,1,.8,.6,1,.9,.75],
  collapse: [1,.18,.9,.22,1,.28,.85,.15],
  pump:     [.28,.45,.6,.78,.5,.9,1,.68] };
const secAmp = (ACT[P.act] || ACT.flail)[((K.section % 8) + 8) % 8];
S.amp += (secAmp - S.amp) * .03;
const inflate = S.amp;
const gravDir = fr(9) > .5 ? 1 : -1;

// ---- wind signal (continuous, K.t-driven -> never re-phases) ----
const bt = K.t * P.speed;
const baseWind = Math.sin(bt * 1.7 + fr(1) * 6) * .55
               + Math.sin(bt * 0.9 + fr(2) * 6) * .35
               + Math.sin(bt * 3.4 + fr(4) * 6) * .22;
const slowGust = 0.5 + 0.5 * Math.sin(bt * 0.45 + fr(3) * 6);
const bassGust = S.bass * P.gust * Math.sin(bt * 2.3 + fr(5) * 6);
const amp = P.energy * (0.5 + 0.9 * K.intensity);
const wind = (baseWind * (0.7 + 0.6 * slowGust) + bassGust) * amp;

// ---- integrate spine chain (semi-implicit, damped, stable) ----
for (let i = 0; i < N; i++) {
  const h = i / (N - 1);
  const below = i > 0 ? S.seg[i - 1].ang : 0;
  const rest = below + (1 - inflate) * gravDir * 1.35 * h;   // droops over when deflated
  const spring = (rest - S.seg[i].ang) * .22;
  const drive = wind * (0.22 + 1.15 * h) * (0.35 + 0.65 * inflate) * .17;
  let v = S.seg[i].vel * .855 + (spring + drive);
  v = Math.max(-.8, Math.min(.8, v));
  S.seg[i].vel = v;
  let a = S.seg[i].ang + v * .5;
  S.seg[i].ang = Math.max(-2.6, Math.min(2.6, a));
}
// arms flail harder, looser spring
function stepArm(arr, side) {
  for (let i = 0; i < arr.length; i++) {
    const h = (i + 1) / arr.length;
    const below = i > 0 ? arr[i - 1].ang : 0;
    const spring = (below * .5 - arr[i].ang) * .16;
    const drive = (wind * 1.5 + side * 0.25) * (0.4 + h) * .22;
    let v = arr[i].vel * .8 + (spring + drive);
    v = Math.max(-1.1, Math.min(1.1, v));
    arr[i].vel = v;
    arr[i].ang = Math.max(-2.9, Math.min(2.9, arr[i].ang + v * .5));
  }
}
stepArm(S.armL, -1); stepArm(S.armR, 1);

// ---- build spine points ----
const X = [bx], Y = [by], DIR = [];
let px = bx, py = by;
for (let i = 0; i < N; i++) {
  const dir = -Math.PI / 2 + S.seg[i].ang;
  DIR.push(dir);
  px += Math.cos(dir) * segLen; py += Math.sin(dir) * segLen;
  X.push(px); Y.push(py);
}
const Wd = i => { const t = i / N; const bulge = 0.55 + 0.5 * Math.sin(Math.min(1, t * 1.05) * Math.PI); const tip = 1 - 0.55 * Math.max(0, t - 0.8) / 0.2; return maxW * Math.max(0.14, bulge * tip); };

// ---- palette ----
const secKick = Math.floor(fr(100 + (((K.section % 8) + 8) % 8)) * 6) * 30;   // color pop per section
const HB = (P.hue + secKick) % 360;
const sheen = 60 + 30 * K.swell + S.tre * 40;
function stripe(i) {
  if (chrome) { const b = 30 + 55 * (i % 2); return [ (HB + 4) % 360, 10, b ]; }
  if (riso) return (i % 2) ? [HB, 82, 92] : [ (HB + 165) % 360, 74, 88 ];
  if (neon) return [ (HB + i * 16) % 360, 88, 100 ];
  return [ (HB + (i % 3) * 44) % 360, 92, 96 ];   // carlot: loud primaries
}

// ================= RENDER =================
push();

// base blower box + skirt shadow
if (!wire) {
  noStroke();
  fill(0, 0, 0, 22); ellipse(bx, by + maxW * .35, maxW * 3.4, maxW * 1.1);   // ground shadow
  fill(chrome ? color(HB,6,38) : neon ? color(HB,30,22) : color(HB, 25, 34));
  rectMode(CENTER); rect(bx, by + maxW * .5, maxW * 2.2, maxW * 1.1, maxW * .12); rectMode(CORNER);
  fill(HB, 20, 55, 60); rect(bx - maxW * 1.1, by + maxW * .1, maxW * 2.2, maxW * .18);
} else {
  stroke(200, 40, 100); strokeWeight(1); noFill();
  rectMode(CENTER); rect(bx, by + maxW * .5, maxW * 2.2, maxW * 1.1); rectMode(CORNER);
}

// ---- tube body ----
if (wire) {
  // schematic skeleton: spine, joint nodes, force vector
  stroke(195, 45, 100); strokeWeight(Math.max(1.2, u * .004));
  noFill(); beginShape(); for (let i = 0; i <= N; i++) vertex(X[i], Y[i]); endShape();
  for (let i = 0; i <= N; i++) {
    const nn = i / N;
    stroke(HB, 60, 100); strokeWeight(1);
    fill(210, 55, 22); circle(X[i], Y[i], maxW * (.4 + .25 * (1 - nn)));
    noFill();
  }
  // width envelope (dashed)
  stroke(HB, 30, 100, 45); strokeWeight(1);
  for (let s = -1; s <= 1; s += 2) {
    beginShape(); for (let i = 0; i <= N; i++) { const d = i < N ? DIR[i] : DIR[N - 1]; vertex(X[i] - Math.sin(d) * s * Wd(i) / 2, Y[i] + Math.cos(d) * s * Wd(i) / 2); } endShape();
  }
  // wind force arrow at tip
  stroke(15, 90, 100); strokeWeight(2);
  const tipx = X[N], tipy = Y[N], fl = wind * u * .05;
  line(tipx, tipy, tipx + fl, tipy); line(tipx + fl, tipy, tipx + fl - Math.sign(fl || 1) * u * .01, tipy - u * .008);
} else {
  if (neon) { blendMode(ADD); }
  noStroke();
  for (let i = 0; i < N; i++) {
    const d = DIR[i], nx = -Math.sin(d), ny = Math.cos(d);
    const w0 = Wd(i) / 2, w1 = Wd(i + 1) / 2;
    const c = stripe(i);
    if (neon) {
      // glowing translucent core + bright edge
      for (let g = 2; g >= 0; g--) { fill(c[0], c[1], c[2], g === 0 ? 90 : 16); const e = g * maxW * .25;
        quad(X[i]-nx*(w0+e),Y[i]-ny*(w0+e), X[i]+nx*(w0+e),Y[i]+ny*(w0+e), X[i+1]+nx*(w1+e),Y[i+1]+ny*(w1+e), X[i+1]-nx*(w1+e),Y[i+1]-ny*(w1+e)); }
    } else {
      fill(c[0], c[1], c[2]);
      quad(X[i]-nx*w0,Y[i]-ny*w0, X[i]+nx*w0,Y[i]+ny*w0, X[i+1]+nx*w1,Y[i+1]+ny*w1, X[i+1]-nx*w1,Y[i+1]-ny*w1);
      // inflatable sheen: bright stripe down the light side
      fill(chrome ? color(HB,3,100,sheen*.9) : color(0,0,100,sheen*.5));
      quad(X[i]-nx*w0,Y[i]-ny*w0, X[i]-nx*w0*.45,Y[i]-ny*w0*.45, X[i+1]-nx*w1*.45,Y[i+1]-ny*w1*.45, X[i+1]-nx*w1,Y[i+1]-ny*w1);
      // core shadow on the far side
      fill(stripe(i)[0], Math.min(100,stripe(i)[1]+10), stripe(i)[2]*.55, 55);
      quad(X[i]+nx*w0*.55,Y[i]+ny*w0*.55, X[i]+nx*w0,Y[i]+ny*w0, X[i+1]+nx*w1,Y[i+1]+ny*w1, X[i+1]+nx*w1*.55,Y[i+1]+ny*w1*.55);
    }
  }
  if (neon) blendMode(BLEND);
  // rounded tip cap
  const dT = DIR[N - 1];
  fill(stripe(N - 1)[0], stripe(N - 1)[1], stripe(N - 1)[2]);
  if (neon) { blendMode(ADD); fill(stripe(N-1)[0],stripe(N-1)[1],100,70); }
  circle(X[N], Y[N], Wd(N));
  if (neon) blendMode(BLEND);
}

// ---- arms ----
function drawArm(arr, side) {
  const ai = Math.round(N * 0.66);
  let ax = X[ai], ay = Y[ai];
  let dir = DIR[Math.min(ai, N - 1)] + side * 1.15;       // splay outward
  const aLen = segLen * 1.15, aW = maxW * 0.5;
  const xs = [ax], ys = [ay], ds = [];
  for (let i = 0; i < arr.length; i++) {
    dir += arr[i].ang * (0.7 + i * .3);
    ds.push(dir);
    ax += Math.cos(dir) * aLen; ay += Math.sin(dir) * aLen;
    xs.push(ax); ys.push(ay);
  }
  if (wire) {
    stroke(195, 45, 100); strokeWeight(Math.max(1, u * .003)); noFill();
    beginShape(); for (let i = 0; i < xs.length; i++) vertex(xs[i], ys[i]); endShape();
    for (let i = 0; i < xs.length; i++) circle(xs[i], ys[i], maxW * .25);
    return;
  }
  noStroke();
  if (neon) blendMode(ADD);
  for (let i = 0; i < arr.length; i++) {
    const d = ds[i], nx = -Math.sin(d), ny = Math.cos(d);
    const w0 = aW * (1 - i / (arr.length + 1)) / 2, w1 = aW * (1 - (i + 1) / (arr.length + 1)) / 2;
    const c = stripe(i + 1);
    fill(c[0], c[1], c[2], neon ? 80 : 100);
    quad(xs[i]-nx*w0,ys[i]-ny*w0, xs[i]+nx*w0,ys[i]+ny*w0, xs[i+1]+nx*w1,ys[i+1]+ny*w1, xs[i+1]-nx*w1,ys[i+1]-ny*w1);
  }
  // hand blob
  const c = stripe(arr.length);
  fill(c[0], c[1], neon ? 100 : c[2], neon ? 75 : 100);
  circle(xs[xs.length - 1], ys[ys.length - 1], aW * .8);
  if (neon) blendMode(BLEND);
}
drawArm(S.armL, -1); drawArm(S.armR, 1);

// ---- face near top ----
if (P.face > 0.02 && !wire) {
  const fi = Math.round(N * 0.86);
  const fx = X[fi], fy = Y[fi], d = DIR[Math.min(fi, N - 1)];
  const nx = -Math.sin(d), ny = Math.cos(d), fwd = { x: Math.cos(d), y: Math.sin(d) };
  const es = maxW * .34 * P.face;
  push(); translate(fx, fy);
  const blink = (K.beat % 4 < 0.12) ? .18 : 1;              // occasional blink
  for (let s = -1; s <= 1; s += 2) {
    const ex = nx * s * maxW * .3, ey = ny * s * maxW * .3;
    fill(0, 0, 100); noStroke(); ellipse(ex, ey, es * 1.5, es * 1.5 * blink);
    // pupil drifts with wind (googly)
    const gx = Math.cos(bt * 4 + s) * es * .3, gy = Math.sin(bt * 3.3 + s) * es * .3;
    fill(0, 0, 8); circle(ex + gx, ey + gy, es * .7);
  }
  // grin
  stroke(0, 0, 12); strokeWeight(maxW * .12); noFill();
  const m = fwd;
  arc(m.x * maxW * .28, m.y * maxW * .28 + es * .2, maxW * .8, maxW * .5, 0.15, Math.PI - 0.15);
  pop();
}

drawingContext.shadowBlur = 0;
blendMode(BLEND);
pop();
